    description: '在太空中跳跃躲避障碍物，收集星星得分',
    html: `<!DOCTYPE html><html><head><meta charset="UTF-8"><style>*{margin:0;padding:0}body{background:#0a0a2e;overflow:hidden}canvas{display:block}#controls{position:fixed;top:8px;right:8px;background:rgba(0,0,0,.8);color:#fff;padding:8px 14px;border-radius:8px;font:13px sans-serif;z-index:10;border:1px solid #444}#controls b{color:#ffd700}#score{position:fixed;top:8px;left:8px;color:#fff;font:bold 20px monospace;z-index:10;text-shadow:0 0 10px #0ff}</style></head><body><div id="controls"><b>操作说明</b><br>空格键 / 点击 = 跳跃<br>躲避障碍 收集星星 ⭐</div><div id="score">得分: 0</div><canvas id="c"></canvas><script>const c=document.getElementById('c'),x=c.getContext('2d');c.width=innerWidth;c.height=innerHeight;let score=0,gameOver=false,jump=false,py=c.height-80,vy=0,g=.6,px=100,obs=[],stars=[],frame=0;function addObs(){obs.push({x:c.width+20,y:c.height-60,w:25+Math.random()*20,h:25+Math.random()*35,color:'hsl('+(Math.random()*60)+',100%,50%)'})}function addStar(){stars.push({x:c.width+20,y:c.height-120-Math.random()*100,r:12})}document.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();if(!jump&&!gameOver){jump=true;vy=-11}}if(gameOver&&e.code==='Space'){score=0;obs=[];stars=[];gameOver=false;frame=0}});c.addEventListener('click',()=>{if(!jump&&!gameOver){jump=true;vy=-11}if(gameOver){score=0;obs=[];stars=[];gameOver=false;frame=0}});function loop(){x.fillStyle='#0a0a2e';x.fillRect(0,0,c.width,c.height);for(let i=0;i<50;i++){x.fillStyle='rgba(255,255,255,'+(0.3+Math.random()*0.5)+')';x.fillRect((i*137+frame*0.5)%c.width,(i*97)%c.height,2,2)}x.fillStyle='#1a1a4e';x.fillRect(0,c.height-40,c.width,40);if(gameOver){x.fillStyle='#fff';x.font='bold 36px sans-serif';x.textAlign='center';x.fillText('游戏结束! 点击重新开始',c.width/2,c.height/2);requestAnimationFrame(loop);return}frame++;if(jump){vy+=g;py+=vy;if(py>=c.height-80){py=c.height-80;jump=false;vy=0}}if(frame%150===0)addObs();if(frame%180===0)addStar();for(let i=obs.length-1;i>=0;i--){let o=obs[i];o.x-=2+Math.min(frame/600,4);x.fillStyle=o.color;x.fillRect(o.x,c.height-40-o.h,o.w,o.h);x.fillStyle='rgba(255,255,0,.3)';x.fillRect(o.x-2,c.height-40-o.h-2,o.w+4,3);if(px+30>o.x&&px<o.x+o.w&&py+35>c.height-40-o.h){gameOver=true}if(o.x<-50)obs.splice(i,1)}for(let i=stars.length-1;i>=0;i--){let s=stars[i];s.x-=3.5;x.fillStyle='#ffd700';x.beginPath();x.arc(s.x,s.y,s.r,0,Math.PI*2);x.fill();x.fillStyle='#fff';x.beginPath();x.arc(s.x-3,s.y-3,3,0,Math.PI*2);x.fill();let dx=px+15-s.x,dy=py+15-s.y;if(Math.sqrt(dx*dx+dy*dy)<s.r+15){score+=10;stars.splice(i,1)}if(s.x<-50)stars.splice(i,1)}x.fillStyle='#00e5ff';x.beginPath();x.arc(px+15,py+15,15,0,Math.PI*2);x.fill();x.fillStyle='#fff';x.beginPath();x.arc(px+10,py+10,5,0,Math.PI*2);x.fill();x.fillStyle='#00b0ff';x.fillRect(px+5,py+30,8,10);x.fillRect(px+17,py+30,8,10);if(frame%60===0)score++;document.getElementById('score').textContent='得分: '+score;requestAnimationFrame(loop)}loop()</script></body></html>`
