    description: '扮演忍者在各平台间跳跃，收集金币',
    html: `<!DOCTYPE html><html><head><meta charset="UTF-8"><style>*{margin:0;padding:0}body{background:#1a0a2e;overflow:hidden}canvas{display:block}#controls{position:fixed;top:8px;right:8px;background:rgba(0,0,0,.85);color:#fff;padding:8px 14px;border-radius:8px;font:13px sans-serif;z-index:10;border:1px solid #c44}#controls b{color:#f44}#score{position:fixed;top:8px;left:8px;color:#fff;font:bold 20px monospace;z-index:10;text-shadow:0 0 8px #f00}</style></head><body><div id="controls"><b>操作说明</b><br>← → 方向键 = 移动<br>空格键 = 跳跃<br>收集金币 🪙 到达终点</div><div id="score">🪙 0</div><canvas id="c"></canvas><script>const c=document.getElementById('c'),x=c.getContext('2d');c.width=innerWidth;c.height=innerHeight;let score=0,px=60,py=300,vx=0,vy=0,onGround=false,camX=0;const keys={};document.addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='Space')e.preventDefault()});document.addEventListener('keyup',e=>keys[e.code]=false);const platforms=[{x:0,y:c.height-50,w:300,h:50},{x:250,y:c.height-150,w:120,h:20},{x:420,y:c.height-250,w:100,h:20},{x:580,y:c.height-200,w:130,h:20},{x:750,y:c.height-300,w:110,h:20},{x:900,y:c.height-380,w:100,h:20},{x:1050,y:c.height-320,w:120,h:20},{x:1200,y:c.height-400,w:90,h:20},{x:1350,y:c.height-280,w:140,h:20},{x:1520,y:c.height-350,w:100,h:20},{x:1700,y:c.height-450,w:150,h:20}];const coins=[];platforms.forEach(p=>{if(p.y<c.height-100){coins.push({x:p.x+p.w/2,y:p.y-30,collected:false})}});function loop(){x.fillStyle='#1a0a2e';x.fillRect(0,0,c.width,c.height);for(let i=0;i<30;i++){x.fillStyle='rgba(255,200,200,'+(0.2+Math.random()*0.3)+')';x.fillRect((i*173)%c.width,(i*131)%c.height,1,1)}if(keys['ArrowLeft'])vx=-3;if(keys['ArrowRight'])vx=3;if(!keys['ArrowLeft']&&!keys['ArrowRight'])vx*=0.8;if((keys['Space']||keys['ArrowUp'])&&onGround){vy=-10;onGround=false}vy+=.6;px+=vx;py+=vy;onGround=false;platforms.forEach(p=>{let rx=p.x-camX;if(px+20>p.x&&px<p.x+p.w&&py+30>=p.y&&py+30<=p.y+p.h+10&&vy>=0){py=p.y-30;vy=0;onGround=true}});coins.forEach(coin=>{if(!coin.collected){let dx=(px+10)-coin.x,dy=(py+10)-coin.y;if(Math.sqrt(dx*dx+dy*dy)<25){coin.collected=true;score++}}});if(px>camX+c.width*0.4)camX=px-c.width*0.4;x.save();x.translate(-camX,0);platforms.forEach(p=>{x.fillStyle='#4a3080';x.fillRect(p.x,p.y,p.w,p.h);x.fillStyle='#6a48b0';x.fillRect(p.x,p.y,p.w,4)});coins.forEach(coin=>{if(!coin.collected){x.fillStyle='#ffd700';x.beginPath();x.arc(coin.x,coin.y,10,0,Math.PI*2);x.fill();x.fillStyle='#ffec80';x.font='bold 10px sans-serif';x.textAlign='center';x.fillText('$',coin.x,coin.y+4)}});x.fillStyle='#ff4444';x.fillRect(px,py,20,30);x.fillStyle='#fff';x.fillRect(px+4,py+4,5,5);x.fillRect(px+11,py+4,5,5);x.fillStyle='#222';x.fillRect(px,py+25,7,8);x.fillRect(px+13,py+25,7,8);x.restore();document.getElementById('score').textContent='🪙 '+score;if(py>c.height+100){py=300;px=60;camX=0;score=Math.max(0,score-3)}requestAnimationFrame(loop)}loop()</script></body></html>`
