    description: '控制挡板反弹小球，打碎所有砖块',
    html: `<!DOCTYPE html><html><head><meta charset="UTF-8"><style>*{margin:0;padding:0}body{background:#0d1117;overflow:hidden;display:flex;justify-content:center;align-items:center;height:100vh}canvas{border:2px solid #30363d;border-radius:8px}#controls{position:fixed;top:10px;right:10px;background:rgba(0,0,0,.85);color:#fff;padding:10px 16px;border-radius:8px;font:13px sans-serif;z-index:10;border:1px solid #30363d}#controls b{color:#58a6ff}</style></head><body><div id="controls"><b>操作说明</b><br>← → 方向键 = 移动挡板<br>打碎所有砖块获胜<br>别让球掉落!</div><canvas id="c" width="600" height="500"></canvas><script>const c=document.getElementById('c'),x=c.getContext('2d');let bx=300,by=400,bdx=3,bdy=-4,pw=80,ppx=260,score=0,lives=3,gameOver=false,bricks=[];const colors=['#ff6b6b','#ffd93d','#6bcb77','#4d96ff','#ff6b9d','#c084fc'];for(let r=0;r<5;r++)for(let cl=0;cl<10;cl++)bricks.push({x:cl*58+8,y:r*28+40,w:54,h:24,alive:true,color:colors[r]});document.addEventListener('keydown',e=>{if(e.code==='ArrowLeft')ppx=Math.max(0,ppx-30);if(e.code==='ArrowRight')ppx=Math.min(600-pw,ppx+30)});c.addEventListener('mousemove',e=>{const r=c.getBoundingClientRect();ppx=Math.max(0,Math.min(600-pw,(e.clientX-r.left)-pw/2))});function loop(){x.fillStyle='#0d1117';x.fillRect(0,0,600,500);x.fillStyle='#fff';x.font='14px monospace';x.fillText('得分:'+score+'  生命:❤️'.repeat(lives),10,25);if(gameOver){x.fillStyle='#fff';x.font='bold 28px sans-serif';x.textAlign='center';x.fillText(lives<=0?'游戏结束! 点击重试':'恭喜通关!',300,250);c.onclick=()=>{score=0;lives=3;gameOver=false;bx=300;by=400;bdx=3;bdy=-3;bricks.forEach(b=>b.alive=true)};return}bx+=bdx;by+=bdy;if(bx<=5||bx>=595)bdx*=-1;if(by<=5)bdy*=-1;if(by+bdy>0){if(by>=490&&bx>=ppx&&bx<=ppx+pw){bdy=-Math.abs(bdy);bdx+=(bx-(ppx+pw/2))/15}}if(by>510){lives--;if(lives<=0){gameOver=true}else{bx=300;by=400;bdx=4;bdy=-4}}bricks.forEach(b=>{if(b.alive){if(bx>=b.x&&bx<=b.x+b.w&&by>=b.y&&by<=b.y+b.h){b.alive=false;bdy*=-1;score+=10}x.fillStyle=b.color;x.fillRect(b.x,b.y,b.w,b.h);x.fillStyle='rgba(255,255,255,.2)';x.fillRect(b.x,b.y,b.w,b.h/2)}});x.fillStyle='#58a6ff';x.fillRect(ppx,492,pw,8);x.fillStyle='#8b949e';x.fillRect(bx-6,by-6,12,12);requestAnimationFrame(loop)}loop()</script></body></html>`
