    category: 'shooting',
    description: '驾驶飞船射击外星人，保卫地球',
    html: `<!DOCTYPE html><html><head><meta charset="UTF-8"><style>*{margin:0;padding:0}body{background:#000;overflow:hidden}canvas{display:block}#controls{position:fixed;top:8px;right:8px;background:rgba(0,0,0,.85);color:#0f0;padding:8px 14px;border-radius:8px;font:13px monospace;z-index:10;border:1px solid #0f0}#controls b{color:#0ff}#hud{position:fixed;top:8px;left:8px;color:#0f0;font:bold 16px monospace;z-index:10}</style></head><body><div id="controls"><b>操作说明</b><br>← → 方向键 = 移动飞船<br>空格键 = 发射激光<br>消灭所有外星人!</div><div id="hud">分数: <span id="s">0</span> | 生命: <span id="l">3</span></div><canvas id="c"></canvas><script>const c=document.getElementById('c'),x=c.getContext('2d');c.width=innerWidth;c.height=innerHeight;let px=c.width/2,py=c.height-60,bullets=[],enemies=[],score=0,lives=3,frame=0,gameOver=false,shootCD=0;const keys={};document.addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='Space')e.preventDefault()});document.addEventListener('keyup',e=>keys[e.code]=false);function spawnEnemy(){enemies.push({x:30+Math.random()*(c.width-60),y:-30,w:36,h:30,dy:0.8+Math.random()*1.2,color:'hsl('+(Math.random()*60+0)+',100%,50%)',hp:1})}function loop(){x.fillStyle='#000';x.fillRect(0,0,c.width,c.height);for(let i=0;i<80;i++){x.fillStyle='rgba(255,255,255,'+(0.1+Math.random()*0.3)+')';x.fillRect(Math.random()*c.width,Math.random()*c.height,1,1)}if(gameOver){x.fillStyle='#0f0';x.font='bold 32px monospace';x.textAlign='center';x.fillText('GAME OVER  点击重新开始',c.width/2,c.height/2);c.onclick=()=>{score=0;lives=3;enemies=[];bullets=[];frame=0;gameOver=false};return}frame++;if(keys['ArrowLeft'])px=Math.max(20,px-5);if(keys['ArrowRight'])px=Math.min(c.width-20,px+5);if(keys['Space']&&shootCD<=0){bullets.push({x:px,y:py-15,dy:-8});shootCD=10}if(shootCD>0)shootCD--;if(frame%70===0)spawnEnemy();bullets.forEach((b,i)=>{b.y+=b.dy;x.fillStyle='#0f0';x.fillRect(b.x-1,b.y,3,12);if(b.y<-20)bullets.splice(i,1)});enemies.forEach((e,ei)=>{e.y+=e.dy;x.fillStyle=e.color;x.fillRect(e.x-e.w/2,e.y,e.w,e.h);x.fillStyle='#ff0';x.fillRect(e.x-8,e.y+6,5,5);x.fillRect(e.x+3,e.y+6,5,5);if(e.y>c.height){lives--;enemies.splice(ei,1)}bullets.forEach((b,bi)=>{if(Math.abs(b.x-e.x)<e.w/2&&Math.abs(b.y-e.y)<e.h/2){enemies.splice(ei,1);bullets.splice(bi,1);score+=100}});if(Math.abs(e.x-px)<e.w/2+15&&Math.abs(e.y-py)<e.h/2+15){lives--;enemies.splice(ei,1)}});x.fillStyle='#0af';x.beginPath();x.moveTo(px,py-20);x.lineTo(px-15,py+10);x.lineTo(px+15,py+10);x.closePath();x.fill();x.fillStyle='#0ff';x.beginPath();x.arc(px,py-5,6,0,Math.PI*2);x.fill();document.getElementById('s').textContent=score;document.getElementById('l').textContent='❤️'.repeat(Math.max(0,lives));if(lives<=0)gameOver=true;requestAnimationFrame(loop)}loop()</script></body></html>`
